// CAV Great Room → Allen Study locked native portal. Elected GM only; original Mosaic Brass Key provenance required.
const NS='dicebox-campaign-helper',SCENE='CAVHG06GreatRoom',RID='CAV06R0000000003',PORTAL='CAVHG06STUDYT001',LEDGER='cavStudyDoorUnlocked';
const KEY='Item.CAVSTUDYBRASS001',ORIGIN='Scene.CAVSG05Scene0001.Region.L15BdSqcbCOLPnIN';
const LOCK='__CAV_ALLEN_STUDY_DOOR_BUSY_v001';
if(game.world?.id!=='cabin-in-the-ashen-veil'||game.version!=='14.367'||scene?.id!==SCENE||region?.id!==RID)return;
if(!['tokenMoveIn','tokenMoveWithin'].includes(event?.name))return;
if(!game.ready||!game.user?.isGM||game.users.activeGM?.id!==game.user.id)return;
const incoming=event.data?.token?.document??event.data?.token,token=scene.tokens.get(incoming?.id??event.data?.tokenId);
if(!token||token.hidden||!token.actorId||token.actor?.type!=='character')return;
const actor=token.actor,owners=game.users.contents.filter(u=>u.active&&!u.isGM&&actor.testUserPermission(u,'OWNER'));
const originator=event.userId??event.data?.userId??null;
const player=originator?owners.find(u=>u.id===originator):owners.length===1?owners[0]:null;
if(!player)return;
const original=actor.items.find(i=>i.name==='Brass Key'&&i.getFlag(NS,'cavStudyKeySourceUuid')===KEY&&i.getFlag(NS,'cavStudyKeySourceRegionUuid')===ORIGIN);
if(!original)return;
const ledger=region.getFlag(NS,LEDGER);
if(ledger?.status==='reserved'||ledger?.status==='done')return;
const portal=region.behaviors.get(PORTAL);
if(!portal||portal.type!=='teleportToken'||!portal.disabled||![...portal.system.destinations].includes('Scene.CAVHG05Scene0001.Region.CAVB9AA3D7BE9560'))return;
const busy=globalThis[LOCK]??(globalThis[LOCK]=new Set());if(busy.has(RID))return;busy.add(RID);
try{
 await region.setFlag(NS,LEDGER,{status:'reserved',actorId:actor.id,tokenId:token.id,keySource:KEY});
 await region.updateEmbeddedDocuments('RegionBehavior',[{_id:PORTAL,disabled:false}]);
 if(region.behaviors.get(PORTAL)?.disabled!==false)throw Error('Portal not enabled; reconcile reserved claim');
 await region.setFlag(NS,LEDGER,{status:'done',actorId:actor.id,tokenId:token.id,keySource:KEY,portal:PORTAL});
 try{await ChatMessage.create({speaker:{alias:'Allen Study Door'},content:'<p>The brass key fits. The study lock releases.</p>',whisper:[player.id]});}
 catch(err){console.warn('[CAV Study] Unlock succeeded, message failed',err);}
}catch(err){console.error('[CAV Study] Unlock outcome uncertain; reserved ledger preserved',err);}
finally{busy.delete(RID);}

